function validShape(p){return p&&p.version===1&&Object.hasOwn(C.businesses,p.business)&&Object.hasOwn(C.stages,p.stage)&&Object.hasOwn(C.types,p.type)&&typeof p.title==='string'&&typeof p.lead==='string'&&p.context&&typeof p.context==='object'&&!Array.isArray(p.context)&&p.scope&&typeof p.scope==='object'&&!Array.isArray(p.scope)&&Array.isArray(p.tasks)&&p.tasks.length<=8&&p.tasks.every(t=>t&&typeof t==='object'&&!Array.isArray(t)&&Array.isArray(t.dependsOn)&&t.dependsOn.every(d=>typeof d==='string'))&&Array.isArray(p.parameters)&&p.parameters.every(t=>t&&typeof t==='object')&&Array.isArray(p.equations)&&p.equations.every(e=>e&&typeof e==='object'&&Array.isArray(e.parameterIds)&&e.parameterIds.every(id=>typeof id==='string'));}
