const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));const ctx=document.createElement('canvas').getContext('2d');
function wrap(str,size,width){ctx.font=size+'px "Malgun Gothic",sans-serif';const out=[];String(str||'미입력').split('\n').forEach(p=>{let line='';for(const ch of p){if(line&&ctx.measureText(line+ch).width>width){out.push(line);line=ch;}else line+=ch;}out.push(line);});return out;}
