function overview(){let s=rect(33,189,286,439)+txt(49,219,'수행 목적 · 범위',18,250,1,'#0F243F',700)+txt(49,252,project.scope.purpose,16,250,3)+line(49,330,303,330)+txt(49,356,'포함 범위',12,250,1,'#595959')+txt(49,382,project.scope.included,15,250,4)+txt(49,493,'제외 범위',12,250,1,'#595959')+txt(49,519,project.scope.excluded,15,250,4);const h=439/Math.max(1,project.tasks.length);project.tasks.forEach((t,i)=>{const y=189+i*h;s+='<g data-task-index="'+i+'">'+rect(339,y,668,h-8,'#FFFFFF','#BFBFBF')+rect(339,y,49,h-8,'#0F243F')+txt(352,y+31,t.id,13,30,1,'#FFFFFF',700)+txt(404,y+30,t.name,17,570,1,'#0F243F',700)+txt(404,y+58,'산출물: '+t.output,15,570,1)+txt(404,y+82,'수용 조건: '+t.gate,12,570,1,'#595959')+'</g>';});return s;}
